using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.UIElements;
using UnityEngine.Networking;
namespace APM {
[RequireComponent(typeof(UIDocument))]
public class NativeGameUI : MonoBehaviour {
 public TextAsset worldJson,peopleJson;
 public Font koreanFont;
 GameState s; WorldData world; PersonRecord[] people=Array.Empty<PersonRecord>();
 VisualElement root,content; string tab="career",status="",query="",atlasState=""; bool english; PersonRecord selected,quiz; bool answered;
 string SavePath=>Path.Combine(Application.persistentDataPath,"apm-save.json");
 string T(string ko,string en)=>english?en:ko+" ("+en+")";
 readonly Color background=new Color32(16,25,35,255),panel=new Color32(25,39,54,255),ink=new Color32(238,243,247,255),accent=new Color32(231,199,142,255);
 void OnEnable(){
  root=GetComponent<UIDocument>().rootVisualElement;
  s=new GameState();try{if(File.Exists(SavePath))s=GameRules.Import(File.ReadAllText(SavePath));}catch(Exception e){status=e.Message;}
  english=PlayerPrefs.GetInt("apm-language",0)==1;
  try{if(worldJson!=null)world=GameRules.LoadWorld(worldJson);if(peopleJson==null)peopleJson=Resources.Load<TextAsset>("APM/people");if(peopleJson!=null)people=JsonUtility.FromJson<PeoplePack>(peopleJson.text)?.people??Array.Empty<PersonRecord>();}catch(Exception e){status=e.Message;}
  Draw();
 }
 void Save(){try{File.WriteAllText(SavePath,GameRules.Export(s));}catch(Exception e){status=e.Message;}}
 void Change(Action f){f();Save();Draw();}
 Label Text(string text,int size=15){var l=new Label(text);l.style.color=ink;l.style.fontSize=size;l.style.whiteSpace=WhiteSpace.Normal;l.style.marginBottom=7;return l;}
 Button B(string text,Action click){var b=new Button(click){text=text};b.style.minHeight=44;b.style.marginBottom=6;b.style.marginRight=5;b.style.backgroundColor=panel;b.style.color=ink;b.style.whiteSpace=WhiteSpace.Normal;b.style.fontSize=14;return b;}
 VisualElement Card(string title){var p=new VisualElement();p.style.backgroundColor=panel;p.style.paddingTop=12;p.style.paddingBottom=12;p.style.paddingLeft=12;p.style.paddingRight=12;p.style.marginBottom=12;p.Add(Text(title,19));content.Add(p);return p;}
 VisualElement Row(VisualElement parent){var r=new VisualElement();r.style.flexDirection=FlexDirection.Row;r.style.flexWrap=Wrap.Wrap;parent.Add(r);return r;}
 void Draw(){
 if(root==null)return;root.Clear();root.style.flexGrow=1;root.style.backgroundColor=background;root.style.color=ink;if(koreanFont!=null)root.style.unityFontDefinition=FontDefinition.FromFont(koreanFont);
 var header=new VisualElement();header.style.paddingLeft=14;header.style.paddingTop=12;header.style.paddingRight=14;header.Add(Text("AMERICAN POLITICAL MANAGER · V7",21));header.Add(Text(s.year+" · Q"+s.quarter+" · "+s.name+" · "+s.state+" · "+s.office));header.Add(B(english?"한국어 + English":"English",()=>{english=!english;PlayerPrefs.SetInt("apm-language",english?1:0);Draw();}));root.Add(header);
 var nav=new ScrollView(ScrollViewMode.Horizontal);var nr=Row(nav.contentContainer);nr.style.flexWrap=Wrap.NoWrap;
 foreach(var n in new[]{("career","커리어","Career"),("people","인물","People"),("atlas","주·지도","Atlas"),("elections","선거","Elections"),("congress","의회","Congress"),("history","역사","History"),("quiz","학습","Study"),("settings","설정","Settings")}){var b=B(T(n.Item2,n.Item3),()=>{tab=n.Item1;selected=null;Draw();});if(tab==n.Item1)b.style.color=accent;nr.Add(b);}root.Add(nav);
 var scroll=new ScrollView(ScrollViewMode.Vertical);scroll.style.flexGrow=1;scroll.style.paddingLeft=14;scroll.style.paddingRight=14;content=scroll.contentContainer;root.Add(scroll);
 if(!string.IsNullOrEmpty(status))content.Add(Text(status));switch(tab){case "people":People();break;case "atlas":Atlas();break;case "elections":Elections();break;case "congress":Congress();break;case "history":History();break;case "quiz":Quiz();break;case "settings":Settings();break;default:Career();break;}
 content.Add(Text(T("실제 기록과 가상 모형은 구분됩니다.","Historical records and fictional simulation are distinct."),12));
 }
 void Career(){var p=Card(T("정치인 육성","Career development"));p.Add(Text(T("자금","Funds")+" "+s.funds+" · "+T("체력","Energy")+" "+s.energy+" · "+T("역량","Skill")+" "+s.skill));p.Add(Text(T("지지","Support")+" "+s.support+" · "+T("관계","Network")+" "+s.network+" · "+T("지식","Knowledge")+" "+s.points));var r=Row(p);string[] keys={"study","organize","network","fundraise","rest"},ko={"공부","조직 관리","관계 형성","자금 마련","휴식"};for(int i=0;i<keys.Length;i++){string k=keys[i];r.Add(B(T(ko[i],k),()=>Change(()=>{status=GameRules.Act(s,k)?"":T("활동 불가","Unavailable");})));}p.Add(B(T("다음 분기","Next quarter"),()=>Change(()=>{GameRules.Advance(s);quiz=null;})));}
 IEnumerable<PersonRecord> Active()=>people.Where(p=>p.terms!=null&&p.terms.Any(t=>PoliticalRecords.Active(t,s.year)));
 void Portrait(VisualElement p,PersonRecord record){if(record==null||!System.Text.RegularExpressions.Regex.IsMatch(record.id??"","^[A-Z][0-9]{6}$"))return;var img=new Image();img.style.width=95;img.style.height=120;img.scaleMode=ScaleMode.ScaleToFit;p.Add(img);var local=Resources.Load<Texture2D>("APM/Portraits/"+record.id);if(local!=null){img.image=local;return;}StartCoroutine(FetchPortrait(record.id,img));}
 IEnumerator FetchPortrait(string id,Image img){string dir=Path.Combine(Application.persistentDataPath,"portraits");Directory.CreateDirectory(dir);string path=Path.Combine(dir,id+".jpg");if(File.Exists(path)){var t=new Texture2D(2,2);if(t.LoadImage(File.ReadAllBytes(path))){if(img.panel!=null)img.image=t;yield break;}Destroy(t);}using(var req=UnityWebRequestTexture.GetTexture("https://unitedstates.github.io/images/congress/225x275/"+id+".jpg")){req.timeout=15;yield return req.SendWebRequest();if(req.result==UnityWebRequest.Result.Success){var t=DownloadHandlerTexture.GetContent(req);try{File.WriteAllBytes(path,t.EncodeToJPG());}catch{}if(img.panel!=null)img.image=t;}}}
 void People(){var p=Card(T("정치인 도감","Political directory"));if(selected!=null){p.Add(B(T("목록","Back"),()=>{selected=null;Draw();}));Portrait(p,selected);p.Add(Text(selected.name+" "+(english?"":selected.ko),24));p.Add(Text(selected.birthday??""));foreach(var t in selected.terms??Array.Empty<TermRecord>())p.Add(Text(t.start+" — "+t.end+" · "+t.type+" · "+t.party+" · "+t.state));var item=selected;p.Add(B(T("원자료","Source"),()=>Application.OpenURL(string.IsNullOrEmpty(item.source)?"https://bioguide.congress.gov/":item.source)));p.Add(B(T("인물 수집","Collect"),()=>Change(()=>{if(!s.collection.Contains(item.id))s.collection.Add(item.id);})));p.Add(Text(T("동시대 관계망 (기록상 연결)","Observed peer network"),19));foreach(var peer in Active().Where(x=>x.id!=item.id).Select(x=>(p:x,links:PoliticalRecords.Links(item,x,s.year))).Where(x=>x.links.Length>=2||x.links.Contains("state")).Take(12)){var rec=peer.p;p.Add(B(rec.name+" · "+string.Join(", ",peer.links),()=>{selected=rec;Draw();}));}return;}
 var input=new TextField(T("검색","Search")){value=query};p.Add(input);p.Add(B(T("검색","Search"),()=>{query=input.value;Draw();}));p.Add(Text(people.Length+" "+T("인물 기록","records")));if(people.Length==0)p.Add(Text(T("자산 팩의 people.json을 Resources/APM에 추가하세요.","Import people.json from the asset pack into Resources/APM.")));
 foreach(var a in Active().Where(x=>string.IsNullOrWhiteSpace(query)||(x.name??"").IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0).Take(60)){var item=a;p.Add(B(item.name,()=>{selected=item;Draw();}));}}
 void Atlas(){var p=Card(T("미국의 주 및 역사적 선거구","States and historical districts"));if(world==null){p.Add(Text(T("세계 데이터 미연결","World data not assigned")));return;}
 var state=world.states.FirstOrDefault(x=>x.id==atlasState&&x.admitted<=s.year)??world.states.FirstOrDefault(x=>x.id==s.state);
 if(state!=null){p.Add(Text(state.name+" · "+s.year+" · Congress "+((s.year-1789)/2+1),19));var index=Resources.Load<TextAsset>("APM/native-map-index");var ix=index==null?null:JsonUtility.FromJson<NativeMapIndex>(index.text);var match=NativeMapView.Match(ix,state.name,(s.year-1789)/2+1);
 var asset=match==null?null:Resources.Load<TextAsset>("APM/Maps/"+match.file);if(asset!=null){var map=JsonUtility.FromJson<NativeMapData>(asset.text);if(map!=null){p.Add(new NativeMapView(map));if(!string.IsNullOrEmpty(map.source))p.Add(B(T("원본 지도","Original map"),()=>Application.OpenURL(map.source)));p.Add(Text(T("간략화된 표시용 경계","Simplified display boundaries"),12));}}else p.Add(Text(T("자산 팩 지도 미등록","Map asset unavailable")));}
 var r=Row(p);foreach(var a in world.states.Where(x=>x.admitted<=s.year)){var st=a;r.Add(B(st.id,()=>{atlasState=st.id;Draw();}));}p.Add(B(T("역사 선거구 원자료","Historical district source"),()=>Application.OpenURL("https://cdmaps.polisci.ucla.edu/")));}
 void Elections(){var p=Card(T("가상 선거","Fictional elections"));foreach(var a in new[]{"rep","sen","gov","prez"}){string k=a;p.Add(B((s.target==k?"✓ ":"")+k,()=>Change(()=>s.target=k)));}p.Add(B(T("가상 선거 실행","Run simulation"),()=>Change(()=>{var r=GameRules.RunElection(s,UnityEngine.Random.value);status=r==null?T("선거 불가","Unavailable"):r.won?T("가상 당선","Fictional win"):T("가상 낙선","Fictional loss");})));if(world!=null)foreach(var e in world.elections.Where(x=>x.year==s.year))p.Add(Text(T("실제 결과","Historical result")+": "+e.winner+" · "+e.party));}
 void Congress(){var p=Card(T("가상 입법 관리","Fictional legislature"));if(s.mode!="alternate"||(s.office!="rep"&&s.office!="sen")){p.Add(Text(T("대체역사 의원직에서 활성화","Available in alternate mode while in Congress")));return;}var l=Legislature.Get(s);var b=l.bills.Find(x=>x.stage!="closed");if(b==null){foreach(var a in new[]{"infra","edu","budget"}){string k=a;p.Add(B(T("법안 발의","Create bill")+" · "+k,()=>Change(()=>Legislature.Create(s,k))));}}else{p.Add(Text(b.agenda+" · "+b.stage));p.Add(Text("Committee "+b.committee+" · House "+b.house+" · Senate "+b.senate));string[] actions=b.stage=="draft"?new[]{"refer"}:b.stage=="committee"?new[]{"hearing","markup"}:b.stage=="calendar"?new[]{"schedule"}:b.stage=="floor"||b.stage=="secondChamber"?new[]{"amend","debate","vote"}:b.stage=="reconcile"?new[]{"amend","agree"}:new[]{"present"};foreach(var a in actions.Concat(new[]{"withdraw"})){string k=a;p.Add(B(k,()=>Change(()=>{if(!Legislature.Act(s,b.id,k))status=T("실행 불가","Unavailable");})));}}foreach(var a in l.bills)p.Add(Text("#"+a.id+" · "+a.agenda+" · "+(a.result??a.stage)));}
 void History(){var p=Card(T("역사 기록","Historical archive"));if(world==null)return;foreach(var e in world.events){var item=e;p.Add(B(item.year+" · "+T(item.ko,item.en),()=>Application.OpenURL(item.source)));}foreach(var e in world.elections)p.Add(Text(e.year+" · "+e.winner+" · "+e.party));}
 void Quiz(){if(quiz!=null&&!(quiz.terms??Array.Empty<TermRecord>()).Any(t=>PoliticalRecords.Active(t,s.year)))quiz=null;var p=Card(T("반복 학습","Retrieval practice"));var pool=Active().ToArray();if(pool.Length<4){p.Add(Text(T("인물 데이터 필요","More records required")));return;}if(quiz==null){quiz=pool[UnityEngine.Random.Range(0,pool.Length)];answered=false;}var t=quiz.terms.First(x=>PoliticalRecords.Active(x,s.year));p.Add(Text(T("이 인물은?","Who is this?")));p.Add(Text(t.party+" · "+t.state+" · "+t.type+" · "+t.start+" — "+t.end));if(answered){p.Add(Text(quiz.name));p.Add(B(T("다음 문제","Next"),()=>{quiz=null;Draw();}));return;}var options=pool.Where(x=>x.id!=quiz.id&&x.name!=quiz.name&&!x.terms.Any(z=>z.party==t.party&&z.state==t.state&&z.type==t.type&&z.start==t.start&&z.end==t.end)).OrderBy(x=>UnityEngine.Random.value).Take(3).Concat(new[]{quiz}).OrderBy(x=>UnityEngine.Random.value).ToArray();foreach(var a in options){var id=a.id;p.Add(B(a.name,()=>Change(()=>{bool ok=id==quiz.id;GameRules.Review(s,quiz.id,ok,DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());status=ok?T("정답","Correct"):T("오답","Incorrect");answered=true;})));}}
 void Settings(){var p=Card(T("설정","Settings"));p.Add(Text(SavePath,12));p.Add(B(T("저장","Save"),()=>{Save();status=T("저장됨","Saved");Draw();}));var name=new TextField(T("새 인물","New candidate")){value=s.name};p.Add(name);var year=new IntegerField(T("시작 연도","Start year")){value=s.year};p.Add(year);var state=new TextField(T("주 약칭","State code")){value=s.state};p.Add(state);var mode=new Toggle(T("대체역사","Alternate history")){value=s.mode=="alternate"};p.Add(mode);p.Add(B(T("새 커리어 시작","Start new career"),()=>{int y=Mathf.Clamp(year.value,1900,2026);string st=(state.value??"").Trim().ToUpperInvariant();if(world!=null&&!world.states.Any(x=>x.id==st&&x.admitted<=y)){status=T("해당 연도에 없는 주","Invalid state for year");Draw();return;}s=new GameState{name=name.value,year=y,state=st,mode=mode.value?"alternate":"historyMode"};quiz=null;tab="career";Save();Draw();}));}
 }
}